//! Linux-only, file-backed single-use challenge ledger for the SRQ lifecycle research prototype.
//!
//! IMPORTANT: this crate does not verify digital signatures, attest a target, or authorize
//! an operation. The caller must verify the signed authorization against a trusted policy
//! and independently establish the expected request binding before calling consume.
//! Challenge IDs must be generated by a cryptographically secure random source outside this
//! crate. This component supplies a durable, serialized replay decision only.
//!
//! The ledger is append-only. Each successful issue/consume operation appends a complete
//! record and calls sync_all before returning success. A partial trailing record is treated
//! as corruption and blocks all later operations. Challenge consumption happens before any
//! privileged side effect: a crash after consumption can lose liveness, but retrying the same
//! challenge cannot obtain a second acceptance. A fresh challenge is required for retry.

#[cfg(not(target_os = "linux"))]
compile_error!("srq-challenge-ledger currently requires Linux flock and O_NOFOLLOW semantics");

use std::collections::{HashMap, HashSet};
use std::error::Error;
use std::ffi::c_int;
use std::fmt;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Seek, SeekFrom, Write};
use std::os::fd::AsRawFd;
use std::os::unix::fs::{MetadataExt, OpenOptionsExt, PermissionsExt};
use std::path::{Path, PathBuf};

const HEADER: &str = "SRQ-CHALLENGE-LEDGER-V1\n";
const LOCK_EX: c_int = 2;
// Linux asm-generic/fcntl.h: O_NOFOLLOW == 00400000 octal.
const O_NOFOLLOW: c_int = 0o400000;
const LEDGER_FILE_MODE: u32 = 0o600;
const PRIVATE_DIR_MASK: u32 = 0o077;
pub const MAX_CHALLENGE_LIFETIME_SECS: u64 = 300;

#[link(name = "c")]
extern "C" {
    fn flock(fd: c_int, operation: c_int) -> c_int;
}

#[derive(Debug)]
pub enum LedgerError {
    Io(io::Error),
    UnsafePath(&'static str),
    InvalidInput(&'static str),
    ChallengeExists,
    ChallengeNotFound,
    BindingMismatch,
    AlreadyConsumed,
    NotYetValid,
    Expired,
    Corrupt(&'static str),
}

impl fmt::Display for LedgerError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io(error) => write!(f, "ledger I/O error: {error}"),
            Self::UnsafePath(reason) => write!(f, "unsafe ledger path: {reason}"),
            Self::InvalidInput(reason) => write!(f, "invalid challenge input: {reason}"),
            Self::ChallengeExists => write!(f, "challenge ID already exists"),
            Self::ChallengeNotFound => write!(f, "challenge ID not found"),
            Self::BindingMismatch => write!(f, "challenge request binding mismatch"),
            Self::AlreadyConsumed => write!(f, "challenge already consumed"),
            Self::NotYetValid => write!(f, "challenge is not yet valid"),
            Self::Expired => write!(f, "challenge expired"),
            Self::Corrupt(reason) => write!(f, "challenge ledger corrupt: {reason}"),
        }
    }
}

impl Error for LedgerError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io(error) => Some(error),
            _ => None,
        }
    }
}

impl From<io::Error> for LedgerError {
    fn from(value: io::Error) -> Self {
        Self::Io(value)
    }
}

pub type LedgerResult<T> = Result<T, LedgerError>;

/// Immutable identity fields that an authorization challenge covers.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Binding {
    pub transaction_id: String,
    pub target_digest: String,
    pub plan_digest: String,
    pub artifact_digest: String,
    pub policy_digest: String,
}

impl Binding {
    fn validate(&self) -> LedgerResult<()> {
        for (name, value) in [
            ("transaction_id", self.transaction_id.as_str()),
            ("target_digest", self.target_digest.as_str()),
            ("plan_digest", self.plan_digest.as_str()),
            ("artifact_digest", self.artifact_digest.as_str()),
            ("policy_digest", self.policy_digest.as_str()),
        ] {
            if !is_digest(value) {
                return Err(LedgerError::InvalidInput(match name {
                    "transaction_id" => "transaction_id must be 64 lowercase hexadecimal characters",
                    "target_digest" => "target_digest must be 64 lowercase hexadecimal characters",
                    "plan_digest" => "plan_digest must be 64 lowercase hexadecimal characters",
                    "artifact_digest" => "artifact_digest must be 64 lowercase hexadecimal characters",
                    _ => "policy_digest must be 64 lowercase hexadecimal characters",
                }));
            }
        }
        Ok(())
    }
}

/// Verifier-created challenge. The ID must be 32 bytes of CSPRNG output encoded as 64 lowercase
/// hexadecimal characters. This crate validates the shape but does not generate entropy.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Challenge {
    pub id: String,
    pub binding: Binding,
    pub issued_at_unix_secs: u64,
    pub expires_at_unix_secs: u64,
}

impl Challenge {
    fn validate_static(&self) -> LedgerResult<()> {
        if !is_digest(&self.id) {
            return Err(LedgerError::InvalidInput(
                "challenge ID must be 64 lowercase hexadecimal characters from a CSPRNG",
            ));
        }
        self.binding.validate()?;
        if self.expires_at_unix_secs <= self.issued_at_unix_secs {
            return Err(LedgerError::InvalidInput(
                "challenge expiry must be later than issue time",
            ));
        }
        let lifetime = self.expires_at_unix_secs - self.issued_at_unix_secs;
        if lifetime > MAX_CHALLENGE_LIFETIME_SECS {
            return Err(LedgerError::InvalidInput(
                "challenge lifetime exceeds the 300-second prototype limit",
            ));
        }
        Ok(())
    }
}

#[derive(Default)]
struct State {
    challenges: HashMap<String, Challenge>,
    consumed: HashSet<String>,
}

/// Append-only, process- and thread-serialized challenge ledger.
///
/// The containing directory must already exist and have no group/other permission bits.
/// Each ledger file must be a regular file, have one hard link, and be mode 0600 or stricter.
/// The parent directory and its ancestors remain part of the trusted computing base.
#[derive(Clone, Debug)]
pub struct ChallengeLedger {
    path: PathBuf,
}

impl ChallengeLedger {
    /// Create and durably initialize a new ledger. Fails if a file already exists at path.
    /// The caller must provision a private directory first.
    pub fn initialize(path: impl AsRef<Path>) -> LedgerResult<Self> {
        let path = path.as_ref().to_path_buf();
        ensure_private_parent(&path)?;
        let mut options = OpenOptions::new();
        options
            .read(true)
            .write(true)
            .append(true)
            .create_new(true)
            .mode(LEDGER_FILE_MODE)
            .custom_flags(O_NOFOLLOW);
        let mut file = options.open(&path)?;
        ensure_private_file(&file)?;
        file.write_all(HEADER.as_bytes())?;
        file.sync_all()?;
        sync_parent_directory(&path)?;
        drop(file);
        Self::open(path)
    }

    /// Open an existing ledger and validate all durable records before returning.
    pub fn open(path: impl AsRef<Path>) -> LedgerResult<Self> {
        let ledger = Self {
            path: path.as_ref().to_path_buf(),
        };
        let (file, _state) = ledger.locked_state()?;
        drop(file);
        Ok(ledger)
    }

    /// Durably append a unique, bounded-lifetime challenge.
    ///
    /// now_unix_secs must come from the verifier's selected time source; it is not trusted
    /// merely because it is a numeric timestamp. A caller needing clock-independent freshness
    /// should use an authenticated nonce protocol and a trusted verifier-side lifetime policy.
    pub fn issue(&self, challenge: &Challenge, now_unix_secs: u64) -> LedgerResult<()> {
        challenge.validate_static()?;
        if now_unix_secs < challenge.issued_at_unix_secs {
            return Err(LedgerError::NotYetValid);
        }
        if now_unix_secs >= challenge.expires_at_unix_secs {
            return Err(LedgerError::Expired);
        }

        let (mut file, state) = self.locked_state()?;
        if state.challenges.contains_key(&challenge.id) {
            return Err(LedgerError::ChallengeExists);
        }
        let row = format!(
            "ISSUE\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",
            challenge.id,
            challenge.binding.transaction_id,
            challenge.binding.target_digest,
            challenge.binding.plan_digest,
            challenge.binding.artifact_digest,
            challenge.binding.policy_digest,
            challenge.issued_at_unix_secs,
            challenge.expires_at_unix_secs
        );
        file.write_all(row.as_bytes())?;
        file.sync_all()?;
        Ok(())
    }

    /// Consume exactly once for the exact verified request binding.
    ///
    /// Call only after verifying an authenticated authorization and independently comparing
    /// its signed binding to the intended request. The ledger does not perform that signature
    /// verification itself. A successful return means the consume record was synced before
    /// return; all side effects should occur after this method returns success.
    pub fn consume(
        &self,
        challenge_id: &str,
        expected_binding: &Binding,
        now_unix_secs: u64,
    ) -> LedgerResult<()> {
        if !is_digest(challenge_id) {
            return Err(LedgerError::InvalidInput(
                "challenge ID must be 64 lowercase hexadecimal characters",
            ));
        }
        expected_binding.validate()?;

        let (mut file, state) = self.locked_state()?;
        let challenge = state
            .challenges
            .get(challenge_id)
            .ok_or(LedgerError::ChallengeNotFound)?;

        if challenge.binding != *expected_binding {
            return Err(LedgerError::BindingMismatch);
        }
        if now_unix_secs < challenge.issued_at_unix_secs {
            return Err(LedgerError::NotYetValid);
        }
        if now_unix_secs >= challenge.expires_at_unix_secs {
            return Err(LedgerError::Expired);
        }
        if state.consumed.contains(challenge_id) {
            return Err(LedgerError::AlreadyConsumed);
        }

        let row = format!(
            "CONSUME\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",
            challenge.id,
            challenge.binding.transaction_id,
            challenge.binding.target_digest,
            challenge.binding.plan_digest,
            challenge.binding.artifact_digest,
            challenge.binding.policy_digest,
            now_unix_secs
        );
        file.write_all(row.as_bytes())?;
        // Success is not reported until the append is durably synced.
        file.sync_all()?;
        Ok(())
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    fn locked_state(&self) -> LedgerResult<(File, State)> {
        ensure_private_parent(&self.path)?;

        let mut options = OpenOptions::new();
        options
            .read(true)
            .write(true)
            .append(true)
            .custom_flags(O_NOFOLLOW);
        let mut file = options.open(&self.path)?;
        ensure_private_file(&file)?;

        // flock is associated with this separately opened file description. The lock is
        // released by the kernel when the descriptor closes, including process termination.
        // SAFETY: as_raw_fd returns a valid descriptor for the live File.
        let lock_result = unsafe { flock(file.as_raw_fd(), LOCK_EX) };
        if lock_result != 0 {
            return Err(LedgerError::Io(io::Error::last_os_error()));
        }

        let state = read_state(&mut file)?;
        Ok((file, state))
    }
}

fn is_digest(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn parent_directory(path: &Path) -> &Path {
    path.parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."))
}

fn ensure_private_parent(path: &Path) -> LedgerResult<()> {
    let parent = parent_directory(path);
    let metadata = fs::symlink_metadata(parent)
        .map_err(|_| LedgerError::UnsafePath("parent directory must already exist"))?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(LedgerError::UnsafePath(
            "parent path must be a real directory, not a symlink",
        ));
    }
    if metadata.mode() & PRIVATE_DIR_MASK != 0 {
        return Err(LedgerError::UnsafePath(
            "parent directory must not grant group/other permissions",
        ));
    }
    Ok(())
}

fn ensure_private_file(file: &File) -> LedgerResult<()> {
    let metadata = file.metadata()?;
    if !metadata.is_file() {
        return Err(LedgerError::UnsafePath("ledger must be a regular file"));
    }
    if metadata.nlink() != 1 {
        return Err(LedgerError::UnsafePath(
            "ledger must have exactly one hard link",
        ));
    }
    if metadata.mode() & 0o077 != 0 {
        return Err(LedgerError::UnsafePath(
            "ledger file must not grant group/other permissions",
        ));
    }
    Ok(())
}

fn sync_parent_directory(path: &Path) -> LedgerResult<()> {
    File::open(parent_directory(path))?.sync_all()?;
    Ok(())
}

fn parse_digest(value: &str) -> LedgerResult<String> {
    if !is_digest(value) {
        return Err(LedgerError::Corrupt("malformed digest in journal"));
    }
    Ok(value.to_owned())
}

fn parse_timestamp(value: &str) -> LedgerResult<u64> {
    if value.is_empty() || !value.bytes().all(|byte| byte.is_ascii_digit()) {
        return Err(LedgerError::Corrupt("malformed timestamp in journal"));
    }
    value
        .parse::<u64>()
        .map_err(|_| LedgerError::Corrupt("timestamp out of range in journal"))
}

fn read_state(file: &mut File) -> LedgerResult<State> {
    file.seek(SeekFrom::Start(0))?;
    let mut content = String::new();
    file.read_to_string(&mut content)?;
    if !content.ends_with('\n') {
        return Err(LedgerError::Corrupt("partial trailing record"));
    }

    let mut lines = content[..content.len() - 1].split('\n');
    if lines.next() != Some(HEADER.trim_end_matches('\n')) {
        return Err(LedgerError::Corrupt("header or format version mismatch"));
    }

    let mut state = State::default();
    for line in lines {
        if line.is_empty() || line.contains('\r') {
            return Err(LedgerError::Corrupt("empty or non-canonical journal row"));
        }
        let fields: Vec<&str> = line.split('\t').collect();
        match fields.first().copied() {
            Some("ISSUE") if fields.len() == 9 => {
                let challenge = Challenge {
                    id: parse_digest(fields[1])?,
                    binding: Binding {
                        transaction_id: parse_digest(fields[2])?,
                        target_digest: parse_digest(fields[3])?,
                        plan_digest: parse_digest(fields[4])?,
                        artifact_digest: parse_digest(fields[5])?,
                        policy_digest: parse_digest(fields[6])?,
                    },
                    issued_at_unix_secs: parse_timestamp(fields[7])?,
                    expires_at_unix_secs: parse_timestamp(fields[8])?,
                };
                challenge
                    .validate_static()
                    .map_err(|_| LedgerError::Corrupt("invalid ISSUE record"))?;
                if state
                    .challenges
                    .insert(challenge.id.clone(), challenge)
                    .is_some()
                {
                    return Err(LedgerError::Corrupt("duplicate ISSUE record"));
                }
            }
            Some("CONSUME") if fields.len() == 8 => {
                let id = parse_digest(fields[1])?;
                let binding = Binding {
                    transaction_id: parse_digest(fields[2])?,
                    target_digest: parse_digest(fields[3])?,
                    plan_digest: parse_digest(fields[4])?,
                    artifact_digest: parse_digest(fields[5])?,
                    policy_digest: parse_digest(fields[6])?,
                };
                let consumed_at = parse_timestamp(fields[7])?;
                let challenge = state
                    .challenges
                    .get(&id)
                    .ok_or(LedgerError::Corrupt("CONSUME precedes ISSUE"))?;
                if challenge.binding != binding {
                    return Err(LedgerError::Corrupt("CONSUME binding differs from ISSUE"));
                }
                if consumed_at < challenge.issued_at_unix_secs
                    || consumed_at >= challenge.expires_at_unix_secs
                {
                    return Err(LedgerError::Corrupt("CONSUME timestamp outside challenge lifetime"));
                }
                if !state.consumed.insert(id) {
                    return Err(LedgerError::Corrupt("duplicate CONSUME record"));
                }
            }
            _ => return Err(LedgerError::Corrupt("unknown record type or field count")),
        }
    }
    Ok(state)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::os::unix::fs::symlink;
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::sync::{Arc, Barrier};
    use std::thread;
    use std::time::{SystemTime, UNIX_EPOCH};

    static NEXT_DIR: AtomicU64 = AtomicU64::new(0);

    struct PrivateTempDir(PathBuf);

    impl PrivateTempDir {
        fn new() -> Self {
            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .expect("system time before Unix epoch")
                .as_nanos();
            let suffix = NEXT_DIR.fetch_add(1, Ordering::Relaxed);
            let path = std::env::temp_dir().join(format!(
                "srq-challenge-ledger-{}-{now:x}-{suffix:x}",
                std::process::id()
            ));
            fs::create_dir(&path).expect("create private test directory");
            fs::set_permissions(&path, fs::Permissions::from_mode(0o700))
                .expect("chmod private test directory");
            Self(path)
        }

        fn ledger_path(&self) -> PathBuf {
            self.0.join("ledger.log")
        }
    }

    impl Drop for PrivateTempDir {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }

    fn repeated(ch: char) -> String {
        std::iter::repeat(ch).take(64).collect()
    }

    fn sample_challenge() -> Challenge {
        Challenge {
            id: repeated('a'),
            binding: Binding {
                transaction_id: repeated('b'),
                target_digest: repeated('c'),
                plan_digest: repeated('d'),
                artifact_digest: repeated('e'),
                policy_digest: repeated('f'),
            },
            issued_at_unix_secs: 10,
            expires_at_unix_secs: 110,
        }
    }

    #[test]
    fn consume_is_single_use_across_reopen() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let challenge = sample_challenge();
        ledger.issue(&challenge, 20).expect("issue");
        ledger
            .consume(&challenge.id, &challenge.binding, 21)
            .expect("first consume");

        drop(ledger);
        let reopened = ChallengeLedger::open(&path).expect("reopen valid durable ledger");
        assert!(matches!(
            reopened.consume(&challenge.id, &challenge.binding, 22),
            Err(LedgerError::AlreadyConsumed)
        ));
    }

    #[test]
    fn wrong_binding_does_not_consume_challenge() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let challenge = sample_challenge();
        ledger.issue(&challenge, 20).expect("issue");

        let mut wrong = challenge.binding.clone();
        wrong.artifact_digest = repeated('9');
        assert!(matches!(
            ledger.consume(&challenge.id, &wrong, 21),
            Err(LedgerError::BindingMismatch)
        ));
        ledger
            .consume(&challenge.id, &challenge.binding, 21)
            .expect("right binding still usable");
    }

    #[test]
    fn expiry_boundary_is_exclusive() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let mut challenge = sample_challenge();
        challenge.expires_at_unix_secs = 30;
        ledger.issue(&challenge, 20).expect("issue");
        assert!(matches!(
            ledger.consume(&challenge.id, &challenge.binding, 30),
            Err(LedgerError::Expired)
        ));
        ledger
            .consume(&challenge.id, &challenge.binding, 29)
            .expect("valid before expiry");
    }

    #[test]
    fn future_challenge_is_rejected_without_burning_it() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let challenge = sample_challenge();
        ledger.issue(&challenge, 20).expect("issue");
        assert!(matches!(
            ledger.consume(&challenge.id, &challenge.binding, 9),
            Err(LedgerError::NotYetValid)
        ));
        ledger
            .consume(&challenge.id, &challenge.binding, 20)
            .expect("accept at issued time");
    }

    #[test]
    fn duplicate_issue_is_rejected() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let challenge = sample_challenge();
        ledger.issue(&challenge, 20).expect("issue");
        assert!(matches!(
            ledger.issue(&challenge, 20),
            Err(LedgerError::ChallengeExists)
        ));
    }

    #[test]
    fn excessive_lifetime_is_rejected() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let mut challenge = sample_challenge();
        challenge.expires_at_unix_secs = challenge.issued_at_unix_secs + MAX_CHALLENGE_LIFETIME_SECS + 1;
        assert!(matches!(
            ledger.issue(&challenge, 20),
            Err(LedgerError::InvalidInput(_))
        ));
    }

    #[test]
    fn partial_tail_fails_closed() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let challenge = sample_challenge();
        ledger.issue(&challenge, 20).expect("issue");

        let mut file = OpenOptions::new()
            .append(true)
            .open(ledger.path())
            .expect("open journal for corruption fixture");
        file.write_all(b"CONSUME\tpartial").expect("append partial row");
        file.sync_all().expect("sync partial row");

        assert!(matches!(
            ledger.consume(&challenge.id, &challenge.binding, 21),
            Err(LedgerError::Corrupt("partial trailing record"))
        ));
    }

    #[test]
    fn symlink_to_ledger_is_rejected() {
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let _ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let alias = dir.0.join("alias.log");
        symlink(&path, &alias).expect("create symlink fixture");
        assert!(ChallengeLedger::open(&alias).is_err());
    }

    #[test]
    fn concurrent_replay_race_has_exactly_one_winner() {
        const SUBMISSIONS: usize = 64;
        let dir = PrivateTempDir::new();
        let path = dir.ledger_path();
        let ledger = ChallengeLedger::initialize(&path).expect("initialize");
        let challenge = sample_challenge();
        ledger.issue(&challenge, 20).expect("issue");

        let ledger = Arc::new(ledger);
        let barrier = Arc::new(Barrier::new(SUBMISSIONS));
        let mut threads = Vec::with_capacity(SUBMISSIONS);
        for _ in 0..SUBMISSIONS {
            let ledger = Arc::clone(&ledger);
            let barrier = Arc::clone(&barrier);
            let challenge = challenge.clone();
            threads.push(thread::spawn(move || {
                barrier.wait();
                ledger.consume(&challenge.id, &challenge.binding, 21)
            }));
        }

        let mut accepted = 0;
        let mut replay_rejected = 0;
        let mut unexpected_errors = 0;
        for worker in threads {
            match worker.join().expect("worker panicked") {
                Ok(()) => accepted += 1,
                Err(LedgerError::AlreadyConsumed) => replay_rejected += 1,
                Err(_) => unexpected_errors += 1,
            }
        }
        assert_eq!(accepted, 1);
        assert_eq!(replay_rejected, SUBMISSIONS - 1);
        assert_eq!(unexpected_errors, 0);
    }
}
